.card {
 font-family: arial;
 text-align: center;
 color: black;
 background-color: white;
}

.card {
    font-family: 'Segoe UI', Arial, sans-serif;
    margin: 5px;              /* thêm để đồng bộ với mặt sau */
    line-height: 1.6;
    text-align: center;
    color: #2c3e50;
    background-color: white;
}

/* Các thành phần bên trong giống cả 2 mặt */
.anki-title {
    font-size: 28px;
    font-weight: bold;
    margin-bottom: 15px;
		color: #111111;
}
.anki-separator {
    width: 80%;
    margin: 15px auto;
    border: none;
    border-top: 2px solid #ddd;
}
.anki-detail {
    font-size: 22px;
    color: #111111;
    text-align: center;

}
.anki-detail ul {
    list-style-position: inside;
    margin: 10px 0;
    padding: 0;
}
.anki-detail li {
    margin-bottom: 8px;
}
